from pathlib import Path
import importlib.util,json
import numpy as np
P=Path(__file__).parent;sp=importlib.util.spec_from_file_location('diagnostic',P/'render_geometry.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m);receipt=json.loads((P/'ACTUAL/RECEIPT.json').read_text());rows=[]
for record in receipt['renders']:
 model=m.load_model(record['version']);cam=m.camera(record['view']);world=model['vertices'];B=cam['basis'];position=cam['camera_position'];camera=(world-position)@B.T;view=np.eye(4);view[:3,:3]=B;view[:3,3]=-B@position;homogeneous=np.concatenate([world,np.ones((*world.shape[:-1],1))],axis=-1);camera2=homogeneous@view.T;assert np.max(abs(camera2[...,:3]-camera))<1e-12
 clip=camera2@np.array(cam['projection_matrix']).T;ndc=clip[...,:3]/clip[...,3,None];pixel=np.stack([(ndc[...,0]+1)*m.W/2,(1-ndc[...,1])*m.H/2],axis=-1);formula,depth=cam['project'](world);error=float(np.max(np.linalg.norm(pixel-formula,axis=-1)));assert error<1e-6
 bbox=np.array([pixel.reshape(-1,2).min(0),pixel.reshape(-1,2).max(0)]);bbox_error=float(np.max(abs(bbox-np.array(record['projected_model_bbox_px']))));assert bbox_error<1e-6
 cross=np.cross(camera[:,1]-camera[:,0],camera[:,2]-camera[:,0]);front=np.einsum('ij,ij->i',cross,-camera[:,0])>1e-12;areas=(pixel[:,1,0]-pixel[:,0,0])*(pixel[:,2,1]-pixel[:,0,1])-(pixel[:,1,1]-pixel[:,0,1])*(pixel[:,2,0]-pixel[:,0,0]);lo=np.floor(pixel.min(1));hi=np.ceil(pixel.max(1));visible=front&(abs(areas)>1e-12)&(hi[:,0]>=0)&(lo[:,0]<m.W)&(hi[:,1]>=0)&(lo[:,1]<m.H);assert int(visible.sum())==record['projected_in_view_triangles'];assert int((visible&model['lamps']).sum())==record['projected_lamp_triangles'];assert np.max(abs(-camera[...,2]-depth))<1e-12
 rows.append({'version':record['version'],'view':record['view'],'all_model_vertex_projection_max_error_px':error,'projected_bbox_max_error_px':bbox_error,'independent_camera_space_backface_and_projected_triangle_count':int(visible.sum()),'model_camera_depth_range_m':[float(depth.min()),float(depth.max())],'count_matches_actual_render':True})
out={'status':'PASS_ALL_VERTEX_MATRIX_VS_SOURCE_FORMULA_BBOX_TRIANGLE_COUNT_DEPTH','rows':rows,'scope':'Read-only mathematical verification of software projection, not browser/PBR/photo acceptance'};(P/'ACTUAL/INDEPENDENT-PROJECTION-PROOF.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
